#include <iostream>
#include <vector>
#include <algorithm>

void printVector(const std::vector<int>& vec) {
  for (auto it = vec.cbegin(); it != vec.cend(); ++it) {
    std::cout << *it << ' ';
  }
  std::cout << std::endl;
}

int main() {
  std::vector<int> v1 = {1, 2, 3, 4, 5};
  const std::vector<int> v2 = {6, 7, 8, 9, 10};

  printVector(v1); // Correct: Using cbegin/cend with a non-const vector
  printVector(v2); // Correct: Using cbegin/cend with a const vector

  // This would be incorrect and compile-time error if using begin() on v2
  // for (auto it = v2.begin(); it != v2.end(); ++it) { ... }
  return 0;
}
